def window_hanning(x):
    """Apply a Hann window to ``x``: ``x * 0.5*(1 - cos(2π i/(N-1)))``."""
    x = _np.asarray(x, dtype=float)
    n = len(x)
    if n < 2:
        return x.copy()
    w = 0.5 * (1 - _np.cos(2 * _np.pi * _np.arange(n) / (n - 1)))
    return x * w


def window_none(x):
    """Rectangular window — returns ``x`` unchanged."""
    return _np.asarray(x)


def angle_spectrum(x, Fs=2, window=None, pad_to=None, sides='default'):
    """Compute the angle (phase, unwrapped) spectrum of ``x``."""
    x = _np.asarray(x, dtype=float)
    if window is not None:
        x = window(x)
    n = len(x)
    pad = pad_to or n
    X = _np.fft.rfft(x, n=pad)
    angles = _np.angle(X)
    freqs = _np.fft.rfftfreq(pad, d=1.0 / Fs)
    return angles, freqs


def magnitude_spectrum(x, Fs=2, window=None, pad_to=None, sides='default',
                      scale_by_freq=None):
    """Compute the magnitude (``|FFT|``) spectrum of ``x``."""
    x = _np.asarray(x, dtype=float)
    if window is not None:
        x = window(x)
    n = len(x)
    pad = pad_to or n
    X = _np.fft.rfft(x, n=pad)
    mag = _np.abs(X) / n
    freqs = _np.fft.rfftfreq(pad, d=1.0 / Fs)
    return mag, freqs


def phase_spectrum(x, Fs=2, window=None, pad_to=None, sides='default'):
    """Compute the unwrapped-phase spectrum of ``x``. Differs from
    :func:`angle_spectrum` in that the phase is unwrapped."""
    angles, freqs = angle_spectrum(x, Fs=Fs, window=window, pad_to=pad_to,
                                   sides=sides)
    return _np.unwrap(angles), freqs


def complex_spectrum(x, Fs=2, window=None, pad_to=None, sides='default'):
    """Compute the complex FFT spectrum of ``x``."""
    x = _np.asarray(x, dtype=float)
    if window is not None:
        x = window(x)
    n = len(x)
    pad = pad_to or n
    X = _np.fft.rfft(x, n=pad)
    freqs = _np.fft.rfftfreq(pad, d=1.0 / Fs)
    return X, freqs


def GaussianKDE(dataset, bw_method=None, weights=None):
    """Gaussian kernel density estimate using Silverman's bandwidth.
    Returns an object whose ``__call__(points)`` evaluates the KDE.
    Mirrors upstream's :class:`mlab.GaussianKDE` (just a class wrapper
    around scipy.stats.gaussian_kde when present; this shim uses a
    direct numpy implementation so scipy isn't required).
    """
    data = _np.asarray(dataset, dtype=float)
    if data.ndim == 1:
        data = data[None, :]

    class _KDE:
        def __init__(_self):
            _self.dataset = data
            d, n = data.shape
            # Silverman's rule of thumb.
            sigma = data.std(axis=1, ddof=1).mean() or 1.0
            _self.factor = (n * (d + 2) / 4.0) ** (-1.0 / (d + 4))
            _self.bandwidth = _self.factor * sigma
            _self.d = d
            _self.n = n

        def __call__(_self, points):
            pts = _np.atleast_2d(_np.asarray(points, dtype=float))
            if pts.shape[0] != _self.d and pts.shape[1] == _self.d:
                pts = pts.T
            h = _self.bandwidth
            out = _np.zeros(pts.shape[1])
            for i in range(pts.shape[1]):
                d = (pts[:, i:i + 1] - _self.dataset) / h
                k = _np.exp(-0.5 * (d ** 2).sum(axis=0))
                out[i] = k.sum() / (_self.n * h * (2 * _np.pi) ** 0.5)
            return out

        def evaluate(_self, points):
            return _self.__call__(points)
    return _KDE()


# ─── Added: detrend dispatcher from upstream mlab.py ────────────────


def detrend(x, key=None, axis=None):
    """Dispatcher for detrending — accepts a key (``'mean'``, ``'linear'``,
    ``'none'``) or a callable, and applies the matching method to ``x``.
    """
    if callable(key):
        return key(x)
    fn = {
        None:     detrend_none,
        'none':   detrend_none,
        'mean':   detrend_mean,
        'linear': detrend_linear,
    }.get(key)
    if fn is None:
        raise ValueError(f"unknown detrend key: {key!r}")
    if fn is detrend_linear:
        return fn(x)
    return fn(x, axis=axis)
